mapper.select:
WITH RECURSIVE descendants (id) AS (
    SELECT child.id
    FROM proj_work_item root
    JOIN proj_work_item child ON child.parent_work_item_id = root.id
        AND child.tenant_id = root.tenant_id
        AND child.project_id = root.project_id
        AND child.deleted = 0
    WHERE root.id = #{rootId}
      AND root.project_id = #{projectId}
      AND root.tenant_id = #{tenantId}
      AND root.deleted = 0
    UNION
    SELECT child.id
    FROM proj_work_item child
    JOIN descendants parent ON child.parent_work_item_id = parent.id
    WHERE child.project_id = #{projectId}
      AND child.tenant_id = #{tenantId}
      AND child.deleted = 0
      AND child.id != #{rootId}
)
SELECT id FROM descendants WHERE id != #{rootId} ORDER BY id
